<script lang="ts">
import type{Language}from'./i18n';import{processActions,type ProcessAction}from'./processResponse';import{formatTime}from'./format';let{language}:{language:Language}=$props();const it=$derived(language==='it');let entries=$state<ProcessAction[]>([]),error=$state(''),busy=$state(false),open=$state(false),page=$state(0),loaded=$state(false);const pages=$derived(Math.max(1,Math.ceil(entries.length/5)));const visible=$derived(entries.slice(Math.min(page,pages-1)*5,Math.min(page,pages-1)*5+5));async function read(){if(busy)return;busy=true;error='';try{entries=await processActions();loaded=true;}catch(e){error=String(e);}finally{busy=false;}}function label(status:string){return status==='terminated'?(it?'Arresto confermato':'Exit confirmed'):(it?'Da verificare':'Needs review');}
</script>
<details class="panel process-journal" bind:open ontoggle={(event)=>{if(event.currentTarget.open&&!loaded)void read();}}><summary>{it?'Registro arresti dei processi':'Process stop journal'}</summary><div><p>{it?'Operazioni manuali di questo utente. Il registro conserva fino a 1000 azioni; qui sono lette le ultime 50. Gli esiti incerti non vengono ripetuti automaticamente.':'Manual operations for this user. Up to 1000 actions retained; the latest 50 are read here. Uncertain actions are never retried automatically.'}</p><button class="button secondary" disabled={busy} onclick={read}>{it?'Aggiorna registro':'Refresh journal'}</button>{#if error}<p role="alert">{error}</p>{/if}{#if loaded&&!entries.length}<p>{it?'Nessuna operazione registrata.':'No recorded operation.'}</p>{/if}<ul>{#each visible as item(item.id)}<li><strong>{item.target.name} · {label(item.status)}</strong><small>{formatTime(item.requested_at*1000,language)} · PID {item.target.pid}</small><details><summary>{it?'Dettagli':'Details'}</summary><code>{item.target.executable}</code><p>{item.detail}</p><code>{item.id} · {item.target.creation_filetime}</code></details></li>{/each}</ul>{#if pages>1}<nav><button class="text-button" disabled={page===0} onclick={()=>page--}>{it?'Precedenti':'Previous'}</button><span>{page+1}/{pages}</span><button class="text-button" disabled={page>=pages-1} onclick={()=>page++}>{it?'Successivi':'Next'}</button></nav>{/if}</div></details>
<style>.process-journal{padding:18px 22px}summary{font-size:.83rem;cursor:pointer}p,small,nav{font-size:.73rem;color:var(--muted);line-height:1.7}ul{list-style:none;padding:0}li{padding:14px 0;border-bottom:1px solid var(--border)}strong,small,code{display:block}strong{font-size:.8rem}code{font-size:.7rem;overflow-wrap:anywhere}nav{display:flex;justify-content:space-between}</style>
